func TestGetCveContentsBySource(t *testing.T) {
	published := time.Date(2021, 4, 5, 0, 0, 0, 0, time.UTC)
	modified := published.Add(time.Hour)
	contents := getCveContents("CVE-2021-1234", dbtypes.Vulnerability{
		Title: "title", Description: "summary", References: []string{"https://example.com/ref"},
		PublishedDate: &published, LastModifiedDate: &modified,
		VendorSeverity: dbtypes.VendorSeverity{"debian": dbtypes.SeverityLow, "ubuntu": dbtypes.SeverityMedium},
		CVSS:           dbtypes.VendorCVSS{"nvd": {V2Score: 4.3, V2Vector: "AV:N", V3Score: 7.5, V3Vector: "CVSS:3.1/AV:N"}},
	})
	if len(contents) != 3 {
		t.Fatalf("sources: %#v", contents)
	}
	if contents[models.TrivyDebian][0].Cvss3Severity != "LOW" || contents[models.TrivyUbuntu][0].Cvss3Severity != "MEDIUM" {
		t.Errorf("severities: %#v", contents)
	}
	nvd := contents[models.TrivyNVD][0]
	if nvd.Type != models.TrivyNVD || nvd.CveID != "CVE-2021-1234" || nvd.Title != "title" || nvd.Summary != "summary" || nvd.Cvss2Score != 4.3 || nvd.Cvss2Vector != "AV:N" || nvd.Cvss3Score != 7.5 || nvd.Cvss3Vector != "CVSS:3.1/AV:N" || len(nvd.References) != 1 || !nvd.Published.Equal(published) || !nvd.LastModified.Equal(modified) {
		t.Errorf("nvd: %#v", nvd)
	}
}
